package com.logatron.investigation.application;import com.logatron.investigation.domain.InvestigationModels.*;import com.logatron.investigation.web.InvestigationDtos.CreateInvestigationRequest;import org.junit.jupiter.api.Test;import java.time.*;import java.util.UUID;import static org.assertj.core.api.Assertions.assertThat;
class ControlledInvestigationPlannerTest{private final ControlledInvestigationPlanner planner=new ControlledInvestigationPlanner();private final UUID project=UUID.randomUUID();private final Clock clock=Clock.fixed(Instant.parse("2026-08-30T10:30:00Z"),ZoneOffset.UTC);@Test void mapsOrderQuestionToSealedQuery(){var q=planner.plan(new CreateInvestigationRequest("Why did order demo-order-42 fail?",project,null,null,null,null,null),clock);assertThat(q.identifierType()).isEqualTo(IdentifierType.ORDER_TOKEN);assertThat(q.identifierValue()).isEqualTo("demo-order-42");}@Test void broadQuestionStaysControlledScopeQuery(){var q=planner.plan(new CreateInvestigationRequest("Was Kafka the cause?",project,null,null,null,null,null),clock);assertThat(q.identifierType()).isEqualTo(IdentifierType.SCOPE);assertThat(Duration.between(q.from(),q.to())).isEqualTo(Duration.ofMinutes(30));}}
